context_info = ()
for d in context:
    prompt = "You are given a single document. Extract any information relevant to the following profile and question.\n\nProfile clues (the same person):\n- In their mid-20s, they began dating their partner, who was a teenager at the time.\n- They had three children together.\n- The individual assaulted their sister and assaulted their partner.\n- They completed their education up to the 10th grade.\n\nQuestion we need to answer: What grade was their oldest child in August 2013?\n\nInstructions:\n- From this document, identify any person(s) who match any part of the profile (even partially). Include: name(s), partner's name, ages/timing at relationship start, number of children (with ages if present), any incidents of assault on sister and on partner (with dates if present), education level.\n- VERY IMPORTANT: Extract explicitly if the document mentions the grade level of the oldest child in August 2013. Quote the exact wording whenever possible.\n- If the document contains relevant info, output a concise structured summary with fields: Candidate Name(s), Partner, Relationship Start Ages/Timing, Children, Assault Incidents (sister), Assault Incidents (partner), Education, Oldest Child Grade in August 2013, Quotes.\n- If the document does not contain relevant info, output exactly: No relevant info.\n\nBEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT"
    result = llm_query(prompt)
    context_info = context_info + (result,)

aggregated = "\n\n---\n\n".join(context_info)

final_prompt = "You are given extracted notes from multiple documents about a specific individual. Use them to determine the answer to the user's question.\n\nAs of December 31, 2013, the following is true about the individual we care about:\n- In their mid-20s, they began dating their partner, who was a teenager at the time.\n- They had three children together.\n- The individual assaulted their sister and partner.\n- They completed their education up to the 10th grade.\n\nQuestion: What grade was their oldest child in August 2013?\n\nNotes from documents:\n" + aggregated + "\n\nInstructions:\n- Identify the single individual who best matches all the profile points across the notes.\n- Locate the explicit statement mentioning the oldest child's grade in August 2013. Use the wording from the notes if available (e.g., 'Class 4', 'fourth grade', etc.).\n- If multiple phrasings exist, choose the one directly quoted or most precise.\n- Output only the grade level as a short phrase (e.g., 'fourth grade' or 'Class 4'). Do not include any other words, punctuation, or explanation."

answer = llm_query(final_prompt)
return_result(answer)